                Arrays.asList(TeleportData.TROLLHEIM, TeleportData.HOUSE_TROLLHEIM)
        ));

        // "Mix yellow with blue and add heat, make sure you bring protection.": kill a Green Dragon
        KILL_TASKS.add(new KillTask(
