    private static void charlie(String text, String item) {
        CHALLENGES.add(new SkillChallenge(text, true,
                "Bring " + item + " to Charlie the Tramp, south entrance of Varrock", CHARLIE_TELEPORTS));
    }

    /**
     * Find the challenge whose text matches any of the given clue strings
     * (RuneLite keeps the scroll text and the chat text separately).
     */
    public static SkillChallenge getChallenge(String... clueTexts) {
        for (String text : clueTexts) {
            if (text == null || text.isEmpty()) {
                continue;
            }
            String lower = text.trim().toLowerCase();
            for (SkillChallenge sc : CHALLENGES) {
                if (lower.equals(sc.textMatch.toLowerCase())) {
                    return sc;
                }
            }
        }
        return null;
    }

    static List<SkillChallenge> all() {
        return Collections.unmodifiableList(CHALLENGES);
    }

    public static class SkillChallenge {
        public final String textMatch;
        public final boolean charlie;
        /** Where to do it, or null when the wiki gives no single place. */
        public final String locationNote;
        public final List<TeleportData> teleports;

        SkillChallenge(String textMatch, boolean charlie, String locationNote, List<TeleportData> teleports) {
            this.textMatch = textMatch;
            this.charlie = charlie;
            this.locationNote = locationNote;
            this.teleports = Collections.unmodifiableList(teleports);
        }

        /** Teleports to show: the task spot first, then the trip back to the NPC. */
        public List<TeleportData> teleports(boolean completed) {
            if (charlie) {
                return teleports;
            }
            if (completed) {
                return SHERLOCK_TELEPORTS;
            }
            List<TeleportData> all = new ArrayList<>(teleports);
            for (TeleportData tp : SHERLOCK_TELEPORTS) {
                if (!all.contains(tp)) {
                    all.add(tp);
                }
            }
            return all;
        }

        public String note(boolean completed) {
            if (charlie) {
                return locationNote;
            }
            if (completed) {
                return "Challenge done. Return to Sherlock";
            }
            return (locationNote != null ? locationNote + ". " : "") + "Then return to Sherlock";
        }
    }
}

package com.clueteleporthelper;

import net.runelite.api.coords.WorldPoint;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.function.Predicate;

/**
 * Turns a target tile and an optional hand-picked list into the panel lines.
 * Pure logic with no client access, so it is covered by unit tests.
 */
public class TeleportRanker {

    /** Teleports landing this close to each other are shown on one line. */
    static final int SAME_SPOT_TILES = 5;

    /** Map squares at or above this Y are underground or instanced copies of the surface. */
    static final int UNDERGROUND_Y = 4000;

    private final int count;
    private final boolean combine;
    private final Predicate<TeleportData> allowed;
    private final Predicate<TeleportData> usable;

    /**
     * @param count   how many lines to return
     * @param combine merge teleports that land on the same spot into one line
     * @param allowed teleports that may appear at all (toggles, Wilderness, "only owned")
     * @param usable  teleports the player can use; the rest are greyed out
     */
    public TeleportRanker(int count, boolean combine, Predicate<TeleportData> allowed, Predicate<TeleportData> usable) {
        this.count = Math.max(1, count);
        this.combine = combine;
        this.allowed = allowed;
        this.usable = usable;
    }

    /**
     * Rank teleports for one target. Hand-picked teleports come first in their
     * given order, then the closest of the rest fill the remaining lines.
     *
     * @param target    ground-level clue tile, or null when the step has no tile
     * @param preferred hand-picked teleports (override, key clue, kill task), may be empty
     * @param fill      whether to top up with the closest teleports
     */
    public List<TeleportSuggestion> rank(WorldPoint target, List<TeleportData> preferred, boolean fill) {
        List<TeleportData> candidates = new ArrayList<>();
        for (TeleportData tp : preferred) {
            if (allowed.test(tp) && !candidates.contains(tp)) {
                candidates.add(tp);
            }
        }
        if (fill && target != null) {
            Arrays.stream(TeleportData.values())
                    .filter(tp -> tp.getLocation() != null && allowed.test(tp) && !candidates.contains(tp))
                    .sorted(Comparator.comparingInt(tp -> tp.getLocation().distanceTo(target)))
                    .forEach(candidates::add);
        }

        List<TeleportSuggestion> result = new ArrayList<>();
        for (TeleportData tp : candidates) {
            TeleportSuggestion near = combine ? findSameSpot(result, tp) : null;
            if (near != null) {
                near.addAlternative(tp, usable.test(tp));
            } else if (result.size() < count) {
                result.add(new TeleportSuggestion(tp, distance(tp, target), null, usable.test(tp)));
            }
        }
        return result;
    }

    /**
     * One line per step (three-step cryptic clues): the hand-picked teleport for
     * that spot if there is one, otherwise the closest teleport.
     */
    public List<TeleportSuggestion> rankSteps(List<WorldPoint> stepTargets, List<String> labels,
                                              java.util.function.Function<WorldPoint, List<TeleportData>> preferredFor) {
        List<TeleportSuggestion> result = new ArrayList<>();
        TeleportRanker single = new TeleportRanker(1, combine, allowed, usable);
        for (int i = 0; i < stepTargets.size(); i++) {
            WorldPoint target = stepTargets.get(i);
            List<TeleportData> preferred = preferredFor.apply(target);
            List<TeleportSuggestion> best = single.rank(target, preferred == null ? Collections.emptyList() : preferred, true);
            if (!best.isEmpty()) {
                TeleportSuggestion b = best.get(0);
                TeleportSuggestion labelled = new TeleportSuggestion(b.getPrimary(), b.getDistance(), labels.get(i), b.isUsable());
                for (TeleportData alt : b.getTeleports()) {
                    labelled.addAlternative(alt, usable.test(alt));
                }
                result.add(labelled);
            }
        }
        return result;
    }

    private static TeleportSuggestion findSameSpot(List<TeleportSuggestion> lines, TeleportData tp) {
        if (tp.getLocation() == null) {
            return null;
        }
        for (TeleportSuggestion line : lines) {
            WorldPoint loc = line.getPrimary().getLocation();
            if (loc != null && loc.distanceTo(tp.getLocation()) <= SAME_SPOT_TILES) {
                return line;
            }
        }
        return null;
    }

    /**
     * Straight-line distance, or null when there is no target or when one end is
     * underground or instanced and the other is not (the number would be meaningless).
     */
    static Integer distance(TeleportData tp, WorldPoint target) {
        if (target == null || tp.getLocation() == null) {
            return null;
        }
        boolean targetBelow = target.getY() >= UNDERGROUND_Y;
        boolean teleportBelow = tp.getLocation().getY() >= UNDERGROUND_Y;
        if (targetBelow != teleportBelow) {
            return null;
        }
        return tp.getLocation().distanceTo(target);
    }
}

package com.clueteleporthelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * One line of the panel: a teleport, plus any other teleports that land on
 * (almost) the same tile, the distance to the target and an optional label.
 */
public class TeleportSuggestion {

    private final List<TeleportData> teleports = new ArrayList<>();
    private final Integer distance;
    private final String label;
    private boolean usable;

    TeleportSuggestion(TeleportData primary, Integer distance, String label, boolean usable) {
        this.teleports.add(primary);
        this.distance = distance;
        this.label = label;
        this.usable = usable;
    }

    void addAlternative(TeleportData tp, boolean altUsable) {
        if (teleports.contains(tp)) {
            return;
        }
        if (altUsable && !usable) {
            // Lead with something the player can actually use.
            teleports.add(0, tp);
            usable = true;
        } else {
            teleports.add(tp);
        }
    }

    public TeleportData getPrimary() {
        return teleports.get(0);
    }

    /** All teleports on this line, the primary first. */
    public List<TeleportData> getTeleports() {
        return Collections.unmodifiableList(teleports);
    }

    /** Straight-line tiles from the primary teleport to the target, or null when not meaningful. */
    public Integer getDistance() {
        return distance;
    }

    /** Prefix such as "Step 2", or null. */
    public String getLabel() {
        return label;
    }

    public boolean isUsable() {
        return usable;
    }

    public boolean isWilderness() {
        return getPrimary().isWilderness();
    }

    public String getDestination() {
        return getPrimary().getDestination();
    }

    /** Method hints of every teleport on the line, for example "Games Neck / Minigame". */
    public String getMethodLabel() {
        Set<String> labels = new LinkedHashSet<>();
        for (TeleportData tp : teleports) {
            String m = tp.getMethodLabel();
            if (m != null) {
                labels.add(m);
            }
        }
        return labels.isEmpty() ? null : String.join(" / ", labels);
    }
}

package com.clueteleporthelper;

import net.runelite.api.coords.WorldPoint;

/**
 * Clue steps whose location RuneLite works out from a varbit inside the Clue Scroll
 * plugin. That lookup needs the plugin itself, which other plugins may not access,
 * so the same table is kept here. Values and tiles are copied from RuneLite's
 * CrypticClue (client 1.13.6).
 */
public final class VariableLocationData {

    /** Start of the master cryptic that sends the player to Viggora. */
    static final String VIGGORA_TEXT = "Come brave adventurer, your sense is on fire.";

    /** Varbit RuneLite reads for Viggora's position (1, 2 or 3). */
    public static final int VIGGORA_VARBIT = 815;

    private VariableLocationData() {
    }

    public static boolean isViggora(String clueText) {
        return clueText != null && clueText.startsWith(VIGGORA_TEXT);
    }

    /** Viggora's tile for a varbit value, or null for an unknown value. */
    public static WorldPoint viggoraLocation(int varbitValue) {
        switch (varbitValue) {
            case 1:
                return new WorldPoint(3295, 3934, 1);
            case 2:
                return new WorldPoint(3447, 3547, 1);
            case 3:
                return new WorldPoint(3121, 9995, 0);
            default:
                return null;
        }
    }

    public static String viggoraNote(int varbitValue) {
        switch (varbitValue) {
            case 1:
                return "Viggora is at the Rogues' Castle (deep Wilderness)";
            case 2:
                return "Viggora is in the Slayer Tower";
            case 3:
                return "Viggora is in the Edgeville Dungeon";
            default:
                return null;
        }
    }
}

package com.clueteleporthelper;

import net.runelite.api.coords.WorldPoint;
import net.runelite.client.plugins.cluescrolls.clues.CoordinateClue;
import net.runelite.client.plugins.cluescrolls.clues.CrypticClue;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Detection paths that use RuneLite's own clue classes through public getters only.
 */
public class ClueDetectionTest {

    // ---- H5: Prifddinas coordinate clues are one dig spot, not a multi-step clue ----

    @Test
    public void prifddinasCoordinateClueIsSingleStep() {
        // RuneLite stores Prifddinas dig spots in region 8755 and mirrors them to region 12894
        // (WorldPoint.REGION_MIRRORS), so getLocations returns two points for one spot.
        WorldPoint prif = new WorldPoint(2200, 3290, 0);
        CoordinateClue clue = CoordinateClue.builder()
                .itemId(0)
                .directions("test")
                .location(prif)
                .build();

        // Precondition: RuneLite reports the dig spot and its mirror point.
        assertEquals(2, clue.getLocations(null).length);

        assertFalse(ClueTeleportHelperPlugin.isMultiStep(clue));
        assertEquals(prif, ClueTeleportHelperPlugin.clueLocation(clue));

        // The single spot then gets the hand-picked Prifddinas route.
        LocationOverrides.OverrideResult override = LocationOverrides.getOverride(prif);
        assertNotNull(override);
        assertTrue(override.teleports.contains(TeleportData.PRIFDDINAS));
    }

    @Test
    public void overworldCoordinateClueIsSingleStep() {
        WorldPoint spot = new WorldPoint(3088, 3469, 0);
        CoordinateClue clue = CoordinateClue.builder()
                .itemId(0)
                .directions("test")
                .location(spot)
                .build();
        assertFalse(ClueTeleportHelperPlugin.isMultiStep(clue));
        assertEquals(spot, ClueTeleportHelperPlugin.clueLocation(clue));
    }

    // ---- H2: kill tasks are found from CrypticClue.getText() ----

    private static final String[] KILL_TASK_TEXTS = {
            "In a while...",
            "Ghostly bones.",
            "A demon's best friend holds the next step of this clue.",
            "You'll get licked.",
            "Reflection is the weakness for these eyes of evil.",
            "Let's hope you don't meet a watery death when you encounter this fiend.",
            "You will have to fly high where a sword cannot help you.",
            "Mix yellow with blue and add heat, make sure you bring protection.",
            "You'll have to plug your nose if you use this source of herbs.",
            "You might have to turn over a few stones to progress.",
            "Banish a chilling spirit.",
            "Crush the spirited earth.",
    };

    @Test
    public void everyKillTaskMatchesARuneLiteClue() {
        for (String text : KILL_TASK_TEXTS) {
            CrypticClue clue = CrypticClue.forText(text);
            assertNotNull("RuneLite has no cryptic clue: " + text, clue);
            assertNotNull("No kill task for: " + text, KillTaskData.getKillTask(clue.getText()));
        }
    }

    @Test
    public void ordinaryCrypticIsNotAKillTask() {
        assertNull(KillTaskData.getKillTask("Search the crates in East Ardougne's general store."));
        assertNull(KillTaskData.getKillTask(null));
    }

    // ---- M7: Viggora, whose location RuneLite reads from a varbit ----

    @Test
    public void viggoraIsRecognisedAndMapped() {
        CrypticClue clue = CrypticClue.forText(
                "Come brave adventurer, your sense is on fire. If you talk to me, it's an old god you desire.");
        assertNotNull(clue);
        assertTrue(VariableLocationData.isViggora(clue.getText()));

        assertEquals(new WorldPoint(3295, 3934, 1), VariableLocationData.viggoraLocation(1));
        assertEquals(new WorldPoint(3447, 3547, 1), VariableLocationData.viggoraLocation(2));
        assertEquals(new WorldPoint(3121, 9995, 0), VariableLocationData.viggoraLocation(3));
        assertNull(VariableLocationData.viggoraLocation(0));
        assertNull(VariableLocationData.viggoraNote(0));
    }

    @Test
    public void viggoraLocationCannotBeReadWithoutTheCluePlugin() {
        CrypticClue clue = CrypticClue.forText(
                "Come brave adventurer, your sense is on fire. If you talk to me, it's an old god you desire.");
        WorldPoint loc;
        try {
            loc = ClueTeleportHelperPlugin.clueLocation(clue);
        } catch (RuntimeException e) {
            loc = null;
        }
        // The plugin then falls back to its own varbit table.
        assertNull(loc);
    }

    // ---- bank cache storage ----

    @Test
    public void storedIdsRoundTrip() {
        java.util.Set<Integer> ids = new java.util.HashSet<>(java.util.Arrays.asList(1712, 563, 8007));
        String stored = ClueTeleportHelperPlugin.formatIds(ids);
        assertEquals("563,1712,8007", stored);
        assertEquals(ids, ClueTeleportHelperPlugin.parseIds(stored));
        assertTrue(ClueTeleportHelperPlugin.parseIds(null).isEmpty());
        assertTrue(ClueTeleportHelperPlugin.parseIds("").isEmpty());
        assertEquals(java.util.Collections.singleton(5), ClueTeleportHelperPlugin.parseIds("x,5"));
    }
}

