        assertNull("Lumbridge surface should not have an override", getOverride(3222, 3218));
    }
}

package com.clueteleporthelper;

import net.runelite.api.ItemID;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;

import static org.junit.Assert.*;

public class PlayerTeleportsTest {

    private static final int LUNAR = 2;

    @Test
    public void spellsNeedTheStandardSpellbookOrATab() {
        PlayerTeleports p = new PlayerTeleports();
        p.setOwnedItems(Collections.singleton(ItemID.LAW_RUNE), true);

        p.setSpellbook(PlayerTeleports.STANDARD_SPELLBOOK);
        assertTrue(p.canUse(TeleportData.VARROCK));

        p.setSpellbook(LUNAR);
        assertFalse("Law runes alone do not cast a standard spell on Lunar", p.canUse(TeleportData.VARROCK));

        p.setOwnedItems(Collections.singleton(ItemID.VARROCK_TELEPORT), true);
        assertTrue("A tablet works from any spellbook", p.canUse(TeleportData.VARROCK));
        assertTrue(p.canUse(TeleportData.VARROCK));
        assertFalse(p.canUse(TeleportData.TROLLHEIM));
    }

    @Test
    public void itemsAreJudgedOnlyOnceTheBankIsKnown() {
        PlayerTeleports p = new PlayerTeleports();
        p.setOwnedItems(Collections.emptySet(), false);
        assertTrue(p.canUse(TeleportData.XERICS_GLADE));

        p.setOwnedItems(Collections.emptySet(), true);
        assertFalse(p.canUse(TeleportData.XERICS_GLADE));

        p.setOwnedItems(new HashSet<>(Arrays.asList(ItemID.XERICS_TALISMAN, ItemID.AMULET_OF_GLORY4)), true);
        assertTrue(p.canUse(TeleportData.XERICS_GLADE));
        assertTrue(p.canUse(TeleportData.EDGEVILLE));
        assertFalse(p.canUse(TeleportData.ECTOPHIAL));
    }

    @Test
    public void questsGateItemFreeTransport() {
        PlayerTeleports p = new PlayerTeleports();
        p.setOwnedItems(Collections.singleton(ItemID.PRIFDDINAS_TELEPORT), true);

        p.setQuestUnlocks(true, true, true, true);
        assertTrue(p.canUse(TeleportData.FAIRY_DKR));
        assertTrue(p.canUse(TeleportData.SPIRIT_TREE_GRAND_EXCHANGE));
        assertTrue(p.canUse(TeleportData.HOUSE_PRIFDDINAS));

        p.setQuestUnlocks(false, false, false, false);
        assertFalse(p.canUse(TeleportData.FAIRY_DKR));
        assertFalse(p.canUse(TeleportData.SPIRIT_TREE_GRAND_EXCHANGE));
        assertFalse(p.canUse(TeleportData.HOUSE_PRIFDDINAS));
        assertFalse(p.canUse(TeleportData.QUETZAL_ALDARIN));
        assertTrue("Minigame teleports need no quest", p.canUse(TeleportData.MINIGAME_CASTLE_WARS));
    }

    @Test
    public void teleportItemListCoversKnownItems() {
        assertTrue(PlayerTeleports.allTeleportItemIds().contains(ItemID.XERICS_TALISMAN));
        assertTrue(PlayerTeleports.allTeleportItemIds().contains(ItemID.WATCHTOWER_TELEPORT));
    }
}

package com.clueteleporthelper;

import org.junit.Test;

import java.util.List;

import static org.junit.Assert.*;

public class SkillChallengeDataTest {

    @Test
    public void sherlockChallengeMatchesAndAddsReturnTrip() {
        SkillChallengeData.SkillChallenge sc = SkillChallengeData.getChallenge("Cut a yew log.");
        assertNotNull(sc);
        assertFalse(sc.charlie);

        List<TeleportData> before = sc.teleports(false);
        assertEquals(TeleportData.WOODCUTTING_GUILD, before.get(0));
        assertTrue(before.containsAll(SkillChallengeData.SHERLOCK_TELEPORTS));
        assertTrue(sc.note(false).endsWith("Then return to Sherlock"));

        assertEquals(SkillChallengeData.SHERLOCK_TELEPORTS, sc.teleports(true));
        assertTrue(sc.note(true).contains("Return to Sherlock"));
    }

    @Test
    public void matchingIgnoresCaseAndTriesEveryText() {
        assertNotNull(SkillChallengeData.getChallenge("", null, "cut a yew log."));
        assertNull(SkillChallengeData.getChallenge("Cut a magic log."));
        assertNull(SkillChallengeData.getChallenge((String) null));
    }

    @Test
    public void charlieUsesTheChatText() {
        // RuneLite leaves the scroll text empty for Charlie and keeps the request in the chat text.
        SkillChallengeData.SkillChallenge sc = SkillChallengeData.getChallenge(
                "", "I really need a cooked pike.", "i need to give charlie a cooked pike.");
        assertNotNull(sc);
        assertTrue(sc.charlie);
        assertEquals(SkillChallengeData.CHARLIE_TELEPORTS, sc.teleports(false));
        assertTrue(sc.note(false).contains("Charlie"));
    }

    @Test
    public void allChallengesAreFilledIn() {
        int sherlock = 0;
        int charlie = 0;
        for (SkillChallengeData.SkillChallenge sc : SkillChallengeData.all()) {
            if (sc.charlie) {
                charlie++;
            } else {
                sherlock++;
            }
            assertFalse(sc.note(false).contains("→"));
        }
        assertEquals(8, charlie);
        assertEquals(51, sherlock);
    }
}

package com.clueteleporthelper;

import net.runelite.api.ItemID;
import org.junit.Test;

import java.util.HashSet;
import java.util.Set;

import static org.junit.Assert.*;

public class TeleportDataTest {

    @Test
    public void wildernessFlags() {
        assertTrue(TeleportData.CHAOS_TEMPLE.isWilderness());
        assertTrue(TeleportData.BANDIT_CAMP.isWilderness());
        assertTrue(TeleportData.LAVA_MAZE.isWilderness());
        assertTrue(TeleportData.CEMETERY.isWilderness());
        assertTrue(TeleportData.EDGEVILLE_LEVER.isWilderness());
        assertTrue(TeleportData.ARDOUGNE_LEVER.isWilderness());
        // Ferox Enclave is a safe zone.
        assertFalse(TeleportData.FEROX_ENCLAVE.isWilderness());
        assertFalse(TeleportData.MINIGAME_CLAN_WARS.isWilderness());
        assertFalse(TeleportData.EDGEVILLE.isWilderness());
    }

    @Test
    public void methods() {
        assertEquals(TeleportData.Method.STANDARD_SPELL, TeleportData.WATCHTOWER.getMethod());
        assertEquals(TeleportData.Method.STANDARD_SPELL, TeleportData.TROLLHEIM.getMethod());
        assertEquals(TeleportData.Method.ITEM, TeleportData.HOUSE_TROLLHEIM.getMethod());
        assertEquals(TeleportData.Method.FAIRY_RING, TeleportData.FAIRY_BLR.getMethod());
        assertEquals(TeleportData.Method.SPIRIT_TREE, TeleportData.SPIRIT_TREE_HOSIDIUS.getMethod());
        assertEquals(TeleportData.Method.MINIGAME, TeleportData.MINIGAME_SOUL_WARS.getMethod());
        assertEquals(TeleportData.Method.LEVER, TeleportData.ARDOUGNE_LEVER.getMethod());
        assertTrue(TeleportData.FAIRY_BLR.isNoItem());
        assertFalse(TeleportData.EDGEVILLE.isNoItem());
    }

    @Test
    public void spellsCarryTheirRunesAndTabs() {
        assertTrue(TeleportData.WATCHTOWER.getItemIds().contains(ItemID.WATCHTOWER_TELEPORT));
        assertTrue(TeleportData.WATCHTOWER.getItemIds().contains(ItemID.LAW_RUNE));
        assertTrue(TeleportData.TROLLHEIM.getItemIds().contains(ItemID.LAW_RUNE));
        // Only spells list law runes, so law runes light up only when a spell is suggested.
        for (TeleportData tp : TeleportData.values()) {
            if (tp.getItemIds().contains(ItemID.LAW_RUNE)) {
                assertEquals(tp + " lists law runes", TeleportData.Method.STANDARD_SPELL, tp.getMethod());
            }
        }
    }

    @Test
    public void namesSplitIntoDestinationAndMethod() {
        assertEquals("Edgeville", TeleportData.EDGEVILLE.getDestination());
        assertEquals("Glory", TeleportData.EDGEVILLE.getMethodLabel());
        assertEquals("Legends' Guild", TeleportData.FAIRY_BLR.getDestination());
        assertEquals("Fairy Ring BLR", TeleportData.FAIRY_BLR.getMethodLabel());
        assertEquals("Hosidius", TeleportData.SPIRIT_TREE_HOSIDIUS.getDestination());
        for (TeleportData tp : TeleportData.values()) {
            assertNotNull(tp + " has no method label", tp.getMethodLabel());
            assertNotNull(tp + " has no location", tp.getLocation());
        }
    }

    @Test
    public void fairyRingCodesAreUnique() {
        Set<String> codes = new HashSet<>();
        for (TeleportData tp : TeleportData.values()) {
            if (tp.getMethod() == TeleportData.Method.FAIRY_RING) {
                String code = tp.name().substring("FAIRY_".length());
                assertTrue("Duplicate ring " + code, codes.add(code));
                assertEquals("Fairy Ring " + code, tp.getMethodLabel());
            }
        }
    }

    @Test
    public void overlayTextAvoidsArrows() {
        for (TeleportData tp : TeleportData.values()) {
            assertFalse(tp.getName().contains("→"));
        }
    }
}

package com.clueteleporthelper;

import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Predicate;

import static org.junit.Assert.*;

public class TeleportRankerTest {

    private static final Predicate<TeleportData> ALL = tp -> true;
    private static final Predicate<TeleportData> NO_WILDERNESS = tp -> !tp.isWilderness();

    private static List<TeleportSuggestion> rank(WorldPoint target, int count, boolean combine,
                                                 Predicate<TeleportData> allowed) {
        return new TeleportRanker(count, combine, allowed, ALL).rank(target, Collections.emptyList(), true);
    }

    private static boolean contains(List<TeleportSuggestion> lines, TeleportData tp) {
        return lines.stream().anyMatch(l -> l.getTeleports().contains(tp));
    }

    @Test
    public void returnsRequestedCountClosestFirst() {
        WorldPoint target = new WorldPoint(3213, 3424, 0); // Varrock square
        List<TeleportSuggestion> lines = rank(target, 5, true, ALL);
        assertEquals(5, lines.size());
        assertEquals(TeleportData.VARROCK, lines.get(0).getPrimary());
        for (int i = 1; i < lines.size(); i++) {
            assertTrue(lines.get(i - 1).getDistance() <= lines.get(i).getDistance());
        }
        assertEquals(1, rank(target, 1, true, ALL).size());
        assertEquals(10, rank(target, 10, true, ALL).size());
    }

    @Test
    public void sameSpotTeleportsShareOneLine() {
        WorldPoint target = new WorldPoint(2520, 3571, 0); // Barbarian Assault
        List<TeleportSuggestion> lines = rank(target, 5, true, ALL);
        TeleportSuggestion first = lines.get(0);
        assertTrue(first.getTeleports().contains(TeleportData.BARBARIAN_ASSAULT));
        assertTrue(first.getTeleports().contains(TeleportData.MINIGAME_BARBARIAN_ASSAULT));
        assertEquals("Games Neck / Minigame", first.getMethodLabel());

        // Each destination appears once.
        long lines_with_ba = lines.stream()
                .filter(l -> l.getTeleports().contains(TeleportData.BARBARIAN_ASSAULT)
                        || l.getTeleports().contains(TeleportData.MINIGAME_BARBARIAN_ASSAULT))
                .count();
        assertEquals(1, lines_with_ba);
    }

    @Test
    public void combiningCanBeTurnedOff() {
        WorldPoint target = new WorldPoint(2520, 3571, 0);
        List<TeleportSuggestion> lines = rank(target, 5, false, ALL);
        for (TeleportSuggestion line : lines) {
            assertEquals(1, line.getTeleports().size());
        }
        assertTrue(contains(lines, TeleportData.BARBARIAN_ASSAULT));
        assertTrue(contains(lines, TeleportData.MINIGAME_BARBARIAN_ASSAULT));
    }

    @Test
    public void wildernessTeleportsCanBeAvoided() {
        WorldPoint target = new WorldPoint(3234, 3634, 0); // Chaos Temple, level 15 Wilderness
        assertTrue(contains(rank(target, 5, true, ALL), TeleportData.CHAOS_TEMPLE));

        List<TeleportSuggestion> safe = rank(target, 5, true, NO_WILDERNESS);
        assertEquals(5, safe.size());
        for (TeleportSuggestion line : safe) {
            for (TeleportData tp : line.getTeleports()) {
                assertFalse(tp + " is in the Wilderness", tp.isWilderness());
            }
        }
        // Ferox Enclave is a safe zone and stays available.
        assertTrue(contains(safe, TeleportData.FEROX_ENCLAVE));
    }

    @Test
    public void handPickedTeleportsComeFirstInOrder() {
        WorldPoint target = new WorldPoint(3213, 3424, 0);
        List<TeleportData> preferred = Arrays.asList(TeleportData.DIGSITE, TeleportData.EDGEVILLE);
        List<TeleportSuggestion> lines = new TeleportRanker(5, true, ALL, ALL).rank(target, preferred, true);
        assertEquals(TeleportData.DIGSITE, lines.get(0).getPrimary());
        assertEquals(TeleportData.EDGEVILLE, lines.get(1).getPrimary());
        assertEquals(5, lines.size());
    }

    @Test
    public void handPickedTeleportsRespectFilters() {
        List<TeleportData> preferred = Arrays.asList(TeleportData.LAVA_MAZE, TeleportData.EDGEVILLE);
        List<TeleportSuggestion> lines = new TeleportRanker(5, true, NO_WILDERNESS, ALL)
                .rank(null, preferred, false);
        assertEquals(1, lines.size());
        assertEquals(TeleportData.EDGEVILLE, lines.get(0).getPrimary());
        assertNull("No tile, so no distance", lines.get(0).getDistance());
    }

    @Test
    public void unusableTeleportsAreMarkedAndAUsableTwinLeads() {
        WorldPoint target = new WorldPoint(2520, 3571, 0);
        Predicate<TeleportData> onlyMinigame = tp -> tp != TeleportData.BARBARIAN_ASSAULT;
        List<TeleportSuggestion> lines = new TeleportRanker(5, true, ALL, onlyMinigame)
                .rank(target, Collections.emptyList(), true);
        TeleportSuggestion first = lines.get(0);
        assertTrue(first.isUsable());
        assertEquals(TeleportData.MINIGAME_BARBARIAN_ASSAULT, first.getPrimary());

        Predicate<TeleportData> none = tp -> false;
        List<TeleportSuggestion> grey = new TeleportRanker(3, true, ALL, none)
                .rank(target, Collections.emptyList(), true);
        assertFalse(grey.get(0).isUsable());
    }

    @Test
    public void noItemTeleportsCanBeLeftOut() {
        WorldPoint target = new WorldPoint(3131, 3496, 0); // Edgeville fairy ring
        Predicate<TeleportData> noRings = tp -> tp.getMethod() != TeleportData.Method.FAIRY_RING;
        List<TeleportSuggestion> lines = rank(target, 10, true, noRings);
        for (TeleportSuggestion line : lines) {
            for (TeleportData tp : line.getTeleports()) {
                assertNotEquals(TeleportData.Method.FAIRY_RING, tp.getMethod());
            }
        }
    }

    @Test
    public void distanceHiddenBetweenSurfaceAndUnderground() {
        WorldPoint underground = new WorldPoint(2930, 10193, 0);
        assertNull(TeleportRanker.distance(TeleportData.EDGEVILLE, underground));
        assertNotNull(TeleportRanker.distance(TeleportData.MINIGAME_BLAST_FURNACE, underground));
        assertEquals(Integer.valueOf(0), TeleportRanker.distance(TeleportData.VARROCK, new WorldPoint(3213, 3424, 0)));
        assertNull(TeleportRanker.distance(TeleportData.VARROCK, null));
    }

    @Test
    public void stepsGetOneLineEach() {
        List<WorldPoint> steps = Arrays.asList(new WorldPoint(3213, 3424, 0), new WorldPoint(2840, 3350, 0));
        List<TeleportSuggestion> lines = new TeleportRanker(5, true, ALL, ALL)
                .rankSteps(steps, Arrays.asList("Step 1", "Step 3"),
                        t -> {
                            LocationOverrides.OverrideResult o = LocationOverrides.getOverride(t);
                            return o == null ? null : o.teleports;
                        });
        assertEquals(2, lines.size());
        assertEquals("Step 1", lines.get(0).getLabel());
        assertEquals(TeleportData.VARROCK, lines.get(0).getPrimary());
        assertEquals("Step 3", lines.get(1).getLabel());
        // Entrana uses its hand-picked override.
        assertEquals(TeleportData.DRAYNOR_VILLAGE, lines.get(1).getPrimary());
    }
}
